from pathlib import Path
import json
W=Path(__file__).resolve().parent;S=W/'source/programs/mayhem/src'
def ref(f,t):
 s=(S/f).read_text();return {'path':'programs/mayhem/src/'+f,'line':s[:s.index(t)].count('\n')+1}
rows=[]
def add(n,ctx,auth,effect,limits,body=None):
 rows.append({'instruction':n,'evidence_class':'runtime-bounded','entry':ref('lib.rs','pub fn '+n),'context':ref(*ctx),'body':ref(*body)if body else ref('lib.rs','pub fn '+n),'authorization_accounts':auth,'effects_order':effect,'limits':limits})
add('initialize_global_params',('lib.rs','pub struct InitializeGlobalParams'),'Any signer payer can initialize canonical global-params PDA once.','Allocate254 and set admin to signer; remaining values default.','First-caller bootstrap authority; no fixed admin proof or initialized-deployment claim.')
add('initialize_fee_recipient',('lib.rs','pub struct InitializeFeeRecipient'),'Any signer named admin; canonical global required but no has_one admin; index fee-recipient PDA and WSOL ATA initialized.','Parser creates accounts then handler rejects index>=8; set bump/index only.','No initializer privilege conferred by payer; third-party precreation is admitted source policy.')
for n in ['update_admin','update_trader','update_max_sol_per_sweep','update_max_stable_per_sweep','reset_sol_deployed','reset_stable_deployed','reset_state','stop_trading','resume_trading','update_global_params']:
 add(n,('lib.rs','pub struct Admin'), 'Canonical owned global-params has_one admin signer; CheckedSystem enforces fixed System ID/executable.','Replace selected fields; reset_state clears specified byte ranges/counters but preserves admin/trader/caps/version; stop/resume rejects duplicate state; update_global_params increments version then emits.','Opaque field semantics unresolved; admin can choose zero keys/extreme rates/caps. No outsider setter shown.')
for n,ctx in [('withdraw_admin','WithdrawAdmin'),('withdraw_quote_admin','WithdrawQuoteAdmin')]:
 add(n,('lib.rs','pub struct '+ctx+"<'info>"),'Global admin signer; canonical sol-vault; token path source/destination ATAs bound to vault/admin and quote mint.','Read signed cooldown from opaque bytes, signed addition check, timestamp write then System or token transfer using sol-vault seeds.','Extreme rate addition may panic; custody token behavior delegated; late transfer error requires rollback of timestamp.')
add('extend_account',('lib.rs','pub struct ExtendAccount'),'Any signer funds extension of AMM? no: explicitly Mayhem-owned account with supported discriminator.','No-op when at/above target size; rent shortfall System transfer then resize; event.','User field is not declared mutable although funding CPI needs writable privilege; generated default metas may require explicit writable override. Excluded initializer semantics not inspected.')
for n,ctx in [('sweep_fees','SweepFees'),('sweep_fees_admin','SweepFeesAdmin')]:
 add(n,('lib.rs','pub struct '+ctx+"<'info>"),'Configured trader or admin signer; canonical global; canonical destination ATA for selected quote; fixed legacy token program.','Exactly16 remaining accounts parsed as8 FeeRecipient/token pairs; transfer within cumulative limit, optional native excess, update counter/timestamp, per-recipient exit, final event.','Remaining pairs lack uniqueness/address/mint equality checks locally; token PDA signer and destination mint constrain transfer. Plain rent/counter arithmetic can abort; no arbitrary owned recipient creation demonstrated.',('lib.rs','fn sweep_remaining'))
add('burn_tokens',('instructions/burn.rs','pub struct BurnTokens'),'Permissionless; owned mint-keyed mayhem-state PDA, canonical sol-vault token ATA, canonical external Pump curve.','Deadline<=now and status not Ended; burn entire token vault via fixed-interface token CPI; record amount; events; then Ended.','No trader/global pause required by source; end-state creation invariants excluded. Clock unwrap and late event failure may abort.',('instructions/burn.rs','pub fn handler'))
for n,ctx,file in [('buy','LegacyBuy','buy.rs'),('sell','LegacySell','sell.rs'),('buy_v2','BuyV2','buy_v2.rs'),('sell_v2','SellV2','sell_v2.rs'),('buy_pump_swap','BuyPumpSwap','buy_pump_swap.rs'),('sell_pump_swap','SellPumpSwap','sell_pump_swap.rs')]:
 amm='pump_swap' in n;v2=n.endswith('_v2');buy=n.startswith('buy')
 auth='Configured trader signer via canonical global; mint-keyed Mayhem state and sol-vault PDA; custody token ATA(s); fixed Pump/AMM target and token programs.'
 effect='Pause, signed cooldown, deadline and state transition checks; trader-supplied price reference band; capped reserve-derived sizing; custody-signed external CPI; reload actual balances; signed i128 deployment accounting; '+('positive-counter low-u64-limb risk checks; 'if buy else '')+'event.'
 if amm:effect='Native wrap/close around AMM trade where WSOL; '+effect
 limits='External CPI validates '+('pool/mints/fee account relationships'if amm else'curve/fee/sharing/recipient relationships')+' not all checked locally. retained_reserve_bps>10000 may panic; caller price reference is not an oracle. '+('Low-limb risk truncation needs range invariant. 'if buy else '')+('Typed sizing unwrap retained; no full sizing-equivalence claim.'if amm else'Input/expiry arithmetic and post-CPI deltas can abort.')
 add(n,('instructions/'+file,'pub struct '+ctx+'<'),auth,effect,limits,('instructions/'+file,'pub fn handler'))
D=json.loads((W/'dispatch.json').read_text());assert len(rows)==24 and {r['instruction']for r in rows}=={x['name']for x in D if x['evidence_class']=='runtime-bounded'}
rows.sort(key=lambda x:x['instruction']);rows.append({'instruction':'initialize_mayhem_state','evidence_class':'excluded-opaque','entry':None,'body':None,'context':None,'authorization_accounts':'Not investigated. Absent current source entry.','effects_order':'No source/body/original-window inspection.','limits':'Explicit hard exclusion; retained history does not become current proof.'})
(W/'coverage.json').write_text(json.dumps(rows,indent=2)+'\n')
def loc(x):return f"`{x['path']}:{x['line']}`"if x else 'opaque'
s='# Mayhem source coverage\n\n24 current entries have prior finite runtime evidence. The excluded initializer is an opaque slot, not a reviewed or implemented handler. All conclusions are candidate-source only.\n\n|Entry / evidence / source|Authorization/accounts|Effects/order|Limits|\n|---|---|---|---|\n'
for r in rows:s+=f"|`{r['instruction']}` ({r['evidence_class']})<br>{loc(r['body'])}<br>{loc(r['context'])}|{r['authorization_accounts']}|{r['effects_order']}|{r['limits']}|\n"
(W/'COVERAGE.md').write_text(s.replace('Any signer funds extension of AMM? no: explicitly Mayhem-owned','Any signer funds extension of an explicitly Mayhem-owned'))
# same text cleanup for JSON
for r in rows:r['authorization_accounts']=r['authorization_accounts'].replace('Any signer funds extension of AMM? no: explicitly Mayhem-owned','Any signer funds extension of an explicitly Mayhem-owned')
(W/'coverage.json').write_text(json.dumps(rows,indent=2)+'\n')
